import 'dart:convert';
import 'dart:io';

import 'package:filarithm/core/domain/print_project.dart';
import 'package:filarithm/core/parser/gcode_parser.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  const parser = GcodeParser();

  test('parses Orca multi-colour grams and human duration', () {
    final result = parser.parseText('''
; generated by OrcaSlicer 2.3.1
; filament_type = PLA;PETG
; filament_colour = #FF69B4;#101010
; filament used [g] = 45.2, 10.8
; total estimated time = 2h 15m 30s
''', sourceName: 'orca.gcode');

    expect(result.slicer, SlicerKind.orcaSlicer);
    expect(result.slicerVersion, 'OrcaSlicer 2.3.1');
    expect(result.plates.single.durationSeconds, 8130);
    expect(result.plates.single.durationProvenanceKey, 'total estimated time');
    expect(result.plates.single.materials, hasLength(2));
    expect(result.plates.single.materials[0].totalConsumedMassMg, 45200);
    expect(result.plates.single.materials[0].colorHex, '#FF69B4');
    expect(result.plates.single.materials[1].materialType, 'PETG');
  });

  test('converts Cura filament length to grams', () {
    final result = parser.parseText('''
;Generated with Cura_SteamEngine 5.10
;TIME:8130
;Filament used: 1.52m
''', sourceName: 'cura.gcode');

    expect(result.slicer, SlicerKind.cura);
    expect(result.plates.single.durationSeconds, 8130);
    expect(
      result.plates.single.materials.single.totalConsumedMassMg,
      closeTo(4535, 2),
    );
    expect(
      result.warnings.map((warning) => warning.code),
      contains('length_converted'),
    );
  });

  test('returns explicit warnings for partial unknown metadata', () {
    final result = parser.parseText('; hello', sourceName: 'unknown.gcode');
    expect(result.hasUsableStatistics, isFalse);
    expect(
      result.warnings.map((warning) => warning.code),
      containsAll(['missing_time', 'missing_material', 'unknown_slicer']),
    );
  });

  test('keeps model and purge grams separate while costing their total', () {
    final result = parser.parseText('''
; generated by Bambu Studio 2.1
; model filament [g] = 20, 10
; purge filament [g] = 4, 2
; total estimated time = 1h
''', sourceName: 'purge.gcode');
    expect(result.plates.single.materials, hasLength(2));
    expect(result.plates.single.materials.first.modelMassMg, 20000);
    expect(result.plates.single.materials.first.purgeMassMg, 4000);
    expect(result.plates.single.materials.first.totalConsumedMassMg, 24000);
  });

  test('uses bounded streaming fallback for deep metadata', () async {
    final directory = await Directory.systemTemp.createTemp('filarithm-gcode-');
    final file = File('${directory.path}${Platform.pathSeparator}deep.gcode');
    try {
      await file.writeAsString('''
; generated by Creality Print 6.0
${List.filled(30, 'G1 X10 Y10 E1').join('\n')}
; total filament weight [g] = 30
; print time = 2h 5m
${List.filled(30, 'G1 X20 Y20 E2').join('\n')}
''');
      const tinyEdges = GcodeParser(edgeBytes: 32);
      final result = await tinyEdges.parseFile(file);
      expect(result.hasUsableStatistics, isTrue);
      expect(
        result.plates.single.materials.single.provenanceKey,
        contains('total filament'),
      );
      expect(
        result.warnings.map((warning) => warning.code),
        contains('streaming_metadata_fallback'),
      );
    } finally {
      await directory.delete(recursive: true);
    }
  });

  test('matches the anonymized Creality Print export fixture', () async {
    final fixture = File('test/fixtures/creality/real_export_metadata.gcode');
    final expected = jsonDecode(
      await File('test/fixtures/creality/real_export_metadata.expected.json')
          .readAsString(),
    ) as Map<String, dynamic>;

    final result = await parser.parseFile(fixture);
    final plate = result.plates.single;

    expect(result.slicer.name, expected['slicer']);
    expect(result.slicerVersion, expected['slicerVersion']);
    expect(plate.durationSeconds, expected['durationSeconds']);
    expect(plate.durationProvenanceKey, expected['durationProvenanceKey']);
    expect(
      plate.materials.map((material) => material.totalConsumedMassMg),
      expected['totalConsumedMassMg'],
    );
    expect(
      plate.materials.map((material) => material.provenanceKey),
      expected['materialProvenanceKeys'],
    );
    expect(
      result.warnings.map((warning) => warning.code),
      containsAll(expected['warningCodes'] as List<dynamic>),
    );
  });
}
